"""Numerical comparison with a reference JSON generated by LC0/Eigen.
Usage: python tests/test_native_reference.py /path/tinyAlpha /path/tinygyal-8.pb.gz /path/reference.json
The reference case 07 has an invalid chess position: white pawn c5 attacks black king d6,
so python-chess/LC0 permits a king capture which the native legal move generator forbids.
"""
import json,subprocess,sys
from pathlib import Path
exe,network,ref=map(str,sys.argv[1:4]);data=json.loads(Path(ref).read_text(encoding='utf8'))
text=''
for p in data['positions']:
    if p['source'].startswith('startpos'):
        text+='position startpos'+(' moves '+' '.join(p['moves']) if p['moves'] else '')+'\n'
    else:text+='position fen '+p['fen']+'\n'
    text+='eval\n'
text+='quit\n'
p=subprocess.run([exe,'--network',network],input=text,text=True,capture_output=True,timeout=180,check=True)
chunks=p.stdout.split('info string q ')[1:]
if len(chunks)!=len(data['positions']):raise RuntimeError('Incorrect number of evaluations')
passed=0;skipped=0
for i,(item,chunk) in enumerate(zip(data['positions'],chunks),1):
    q=float(chunk.splitlines()[0]);policy={x[3]:float(x[4]) for l in chunk.splitlines() if (x:=l.split())[:3]==['info','string','policy']}
    qdiff=abs(q-(item['w']-item['l']))
    if i==7:
        assert item['fen'].startswith('8/2p5/3k4/2P5')
        print(f'{i:02} SKIP INVALID_FEN: pawn c5 attacks enemy king d6; qdiff={qdiff:g}')
        skipped+=1;continue
    mismatch=set(policy)^set(item['policy'])
    pdiff=max(abs(policy.get(k,0)-v) for k,v in item['policy'].items())
    ok=qdiff<.003 and pdiff<.003 and not mismatch
    print(f'{i:02} {"PASS" if ok else "FAIL"} qdiff={qdiff:.7g} max_policy_diff={pdiff:.7g} legal_mismatch={len(mismatch)} history={item["history"]}')
    if not ok:sys.exit(1)
    passed+=1
print(f'{passed}/8 valid positions passed, {skipped} invalid FEN skipped')
